import { useState, useRef, useEffect } from "react";
import { Form, InputNumber, DatePicker, Button, Input, Modal, Table, message } from "antd";
import { exportSurverData, getSurveyListData } from "@/api/question-download";
import dayjs from "dayjs";
import { useAntdTable } from "ahooks";
import UserTemplate from "./template";
import { ColumnsType } from "antd/es/table";
import { useGetScrollCount, useTableProps } from "@/hooks";
import { TNumberOrString } from "@/types/common.type";

const getData = (
  params: { current: TNumberOrString; pageSize: TNumberOrString },
  form: Record<string, string | number> = {}
): Promise<any> => {
  const newForm = { ...form };

  if (Array.isArray(newForm.createTime) && newForm.createTime.length > 0) {
    const [startDate, endDate] = newForm.createTime;
    newForm.createTime = [
      `${dayjs(startDate).format("YYYY-MM-DDT00:00:00")}`,
      `${dayjs(endDate).format("YYYY-MM-DDT00:00:00")}`,
    ] as any;
  }

  return getSurveyListData({
    page: params.current,
    size: params.pageSize,
    ...newForm,
  }).then((result) => {
    console.log(result);
    return result;
  });
};

function QuestionDownload() {
  const [form] = Form.useForm();
  const [downLoading, setDownLoading] = useState(false);
  const modalRef = useRef<Record<string, any>>(null);

  const { tableProps, search } = useAntdTable(getData, {
    defaultParams: [{ current: 1, pageSize: 10 }],
    form,
  });

  const columns: ColumnsType<any> = [
    { title: "问卷ID", dataIndex: "surveyId", fixed: "left", width: 150 },
    { title: "问卷标题", dataIndex: "surveyTitle", width: 150 },
    { title: "问题ID", dataIndex: "questionID", width: 150 },
    { title: "问题标题", dataIndex: "questionTitle", width: 170 },
    { title: "测试人ID", dataIndex: "userId", width: 150 },
    {
      title: "回答时间",
      dataIndex: "answerTime",
      width: 250,
      render: (_, record) => <>{dayjs(record?.answerTime).format("YYYY-MM-DD HH:mm:ss")}</>,
    },
  ];

  /**
   * @desc 导出数据
   */
  const exportData = async () => {
    const { createTime, surveyId, userId } = await form.validateFields();
    let params: Record<string, any> = { surveyId, userId };
    if (createTime && Array.isArray(createTime)) {
      const [start, end] = createTime;
      params.createTime = [
        dayjs(start).format("YYYY-MM-DDT00:00:00"),
        dayjs(end).format("YYYY-MM-DDT00:00:00"),
      ];
    }
    setDownLoading(true);
    message.info("正在导出数据中，请耐心等待...");
    try {
      const res = await exportSurverData(params);
      const file = new Blob([res.data], { type: "application/vnd.ms-excel" });
      const url = URL.createObjectURL(file);
      const a = document.createElement("a");
      a.download = surveyId ? `问卷-${surveyId}-调查结果.xlsx` : `问卷调查结果-${+Date.now()}.xlsx`;
      a.href = url;
      a.click();
      message.success("数据导出成功");
    } catch (err) {
      console.log(err);
    } finally {
      setDownLoading(false);
    }
  };

  /**
   * @desc 选择测试人
   */
  const chooseTestUser = async () => {
    Modal.confirm({
      title: "选择测试人",
      content: <UserTemplate ref={modalRef} />,
      icon: null,
      maskClosable: false,
      closable: true,
      width: 520,
      onOk: async () => {
        const { userId } = modalRef.current!;
        form.setFieldValue("userId", userId.current);
      },
    });
  };

  const scrollXCount = useGetScrollCount(columns);

  /**
   * @desc 重置搜索
   * @param {Boolean} bool 是否重置
   */
  const resetSearch = async (bool: boolean = false) => {
    if (bool) {
      form.resetFields();
    }
    return bool ? search.reset() : search.submit();
  };

  return (
    <>
      <div className="mb-6">
        <Form layout="inline" form={form}>
          <Form.Item label="时间段" name="createTime" className="!mb-4">
            <DatePicker.RangePicker style={{ width: "250px" }} />
          </Form.Item>
          <Form.Item label="问卷ID" name="surveyId" className="!mb-4">
            <InputNumber placeholder="请输入问卷ID" controls={false} style={{ width: "200px" }} />
          </Form.Item>
          <Form.Item label="测试人ID" name="userId" className="!mb-4">
            <Input
              placeholder="请选择测试人..."
              disabled
              size={"small"}
              suffix={
                <Button type="primary" onClick={() => chooseTestUser()}>
                  选择测试人
                </Button>
              }
            />
          </Form.Item>
          <Form.Item className="!mb-4">
            <Button type="primary" loading={tableProps.loading} onClick={() => resetSearch()}>
              查询
            </Button>
            <Button type="default" className="ml-2" onClick={() => resetSearch(true)}>
              清空
            </Button>
          </Form.Item>
        </Form>
      </div>
      <div className="my-2 flex justify-end">
        <Button type="primary" loading={downLoading} onClick={() => exportData()}>
          导出问卷
        </Button>
      </div>
      <Table
        columns={columns}
        bordered
        scroll={{ x: scrollXCount }}
        {...useTableProps(tableProps)}
        rowKey="questionID"
      ></Table>
    </>
  );
}

export default QuestionDownload;
